    Bug 2039908 - Prevent GetURIForViewIndex from throwing exceptions on invalid indices. r=mkmelin


    As a follow-up to Bug 1961165, this patch refactors `GetURIForViewIndex` to
    safely return an empty result instead of throwing when trying to find the
    underlying folder for an invalid index (which failed in `nsMsgSearchDBView`).

    This also cleans up two C++ calling sites of `GetViewIndexForFirstSelectedMsg`
    by removing dead error-handling code, as the method cannot fail.

    Differential Revision: https://phabricator.services.mozilla.com/D300786

diff --git a/mailnews/base/content/junkCommands.js b/mailnews/base/content/junkCommands.js
index 217c76c0235..2fc115bee56 100644
--- a/mailnews/base/content/junkCommands.js
+++ b/mailnews/base/content/junkCommands.js
@@ -243,13 +243,11 @@ async function processFolderForJunk(aAll) {
   let tmpMsgURI;
   for (let i = 0; i < totalMessages; i++) {
     const index = aAll ? i : indices[i];
-    try {
-      tmpMsgURI = gDBView.getURIForViewIndex(index);
+    tmpMsgURI = gDBView.getURIForViewIndex(index);
+    if (tmpMsgURI) {
       break;
-    } catch (e) {
-      // dummy headers will fail, so look for another
-      continue;
     }
+    // dummy headers will fail, so look for another
   }
   if (!tmpMsgURI) {
     return;
@@ -266,6 +264,9 @@ async function processFolderForJunk(aAll) {
     const index = aAll ? i : indices[i];
     try {
       const msgURI = gDBView.getURIForViewIndex(index);
+      if (!msgURI) {
+        continue;
+      }
       const msgHdr =
         MailServices.messageServiceFromURI(msgURI).messageURIToMsgHdr(msgURI);
       msgClassifier.analyzeMessage(msgHdr, spamSettings);
